  d < fm_b FAM - 1 -> r < 0 + 1 ->
  lr_lhs (iarm_0RB1LA_1LC1RC_1RA1RD_1RC0LA d r)
    = cls_conf FAM (cls_side FAM [] (fm_b FAM - 1) r
                      (astride 0 1 r) [d]).
