  ph < 1 ->
  ReachL tm true true (lr_lhs (farm_0RB1LA_1LC1RC_1RA1RD_1RC0LA r ph)) (lr_rhs (farm_0RB1LA_1LC1RC_1RA1RD_1RC0LA r ph)).
