Theorem nqhtr_0RB1LD_1RC1RB_1LA1RA_0RC0LD : NeverQuasiHaltsTr tm_0RB1LD_1RC1RB_1LA1RA_0RC0LD.
Proof.
  eapply (boardN_neverqhtr tm_0RB1LD_1RC1RB_1LA1RA_0RC0LD pins_0RB1LD_1RC1RB_1LA1RA_0RC0LD FAM 2
                           iarm_0RB1LD_1RC1RB_1LA1RA_0RC0LD 0 1
                           farm_0RB1LD_1RC1RB_1LA1RA_0RC0LD 1 1
                           fm1_0RB1LD_1RC1RB_1LA1RA_0RC0LD fm2_0RB1LD_1RC1RB_1LA1RA_0RC0LD 0
                           nrules vsegs_0RB1LD_1RC1RB_1LA1RA_0RC0LD vis_0RB1LD_1RC1RB_1LA1RA_0RC0LD
                           [0] 1).
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    destruct ph as [|ph].
    { vm_compute; repeat constructor. }
    exfalso; lia.
  - intros ph Hph.
