  d < fm_b FAM - 1 -> r < 0 + 1 ->
  lr_lhs (iarm_0RB1RB_1LC1RA_0RC1LD_1RA0LC d r)
    = cls_conf FAM (cls_side FAM [] (fm_b FAM - 1) r
                      (astride 0 1 r) [d]).
