Lemma farm_rhs_0RB1RB_1LC1RA_0RC1LD_1RA0LC : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  lr_rhs (farm_0RB1RB_1LC1RA_0RC1LD_1RA0LC r ph)
    = cls_conf FAM (run_side FAM (f_mid (fam_fill FAM ph)) (fm1_0RB1RB_1LC1RA_0RC1LD_1RA0LC r ph)
                      (astride 1 1 r) (fm2_0RB1RB_1LC1RA_0RC1LD_1RA0LC r ph)
                      (f_to (fam_fill FAM ph))
                      (f_pre (fam_fill FAM ph)) (f_suf (fam_fill FAM ph))).
