Lemma fm12_0RB1RB_1LC1RA_0RC1LD_1RA0LC : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 1 ->
  fm1_0RB1RB_1LC1RA_0RC1LD_1RA0LC r ph + fm2_0RB1RB_1LC1RA_0RC1LD_1RA0LC r ph
  + (length (f_pre (fam_fill FAM ph)) + length (f_suf (fam_fill FAM ph)))
  = r + f_s (fam_fill FAM ph).
