  exfalso; lia.
Qed.

Lemma vis_ok_0RB1RB_1LC1RA_0RC1LD_1RA0LC : forall r t, ~ In t pins_0RB1RB_1LC1RA_0RC1LD_1RA0LC -> 0 < r ->
  r < 1 + 1 ->
  nfire tm true true nrules (vsegs_0RB1RB_1LC1RA_0RC1LD_1RA0LC r t) (vis_0RB1RB_1LC1RA_0RC1LD_1RA0LC r t)
    (lr_lhs (farm_0RB1RB_1LC1RA_0RC1LD_1RA0LC r 0)) = Some t.
