    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB0RD_1LC1RD_1LA1LC_0LB0RD : list (LRule * list rstep) :=
  [(mkLRule (mkC StD (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) (mkC StD (mkS [S0] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StC (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StC (mkS [] [] 0 0 []) S1 (mkS [S1] [] 0 0 [])) 0 1, [RB (SWin 1)])].
Local Notation lad := lad_1RB0RD_1LC1RD_1LA1LC_0LB0RD.

Definition rules_1RB0RD_1LC1RD_1LA1LC_0LB0RD : list LRule := map fst lad.
Local Notation rules := rules_1RB0RD_1LC1RD_1LA1LC_0LB0RD.

Lemma ladder_ok_1RB0RD_1LC1RD_1LA1LC_0LB0RD : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB0RD_1LC1RD_1LA1LC_0LB0RD : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB0RD_1LC1RD_1LA1LC_0LB0RD. Qed.

(** ** The arms, as DATA

    Each is a rule the kernel re-derives from the machine.  [el]/[er] record
    whether that side's tail is known empty: the fill arm must see the end
    of the counter, the interior arms hold against an arbitrary tail. *)
(* B[0] L<1^3+y0> R<>  ==>  B[0] L<0^3+y0 1^2> R<>   [12+2*y0 steps] *)
