Qed.

Lemma farm_reach_1RB0RD_1LC1RD_1LA1LC_0LB0RD : forall r ph, 0 < r -> r < 1 + 1 ->
  ph < 2 ->
  ReachL tm true true (lr_lhs (farm_1RB0RD_1LC1RD_1LA1LC_0LB0RD r ph)) (lr_rhs (farm_1RB0RD_1LC1RD_1LA1LC_0LB0RD r ph)).
