    destruct ph as [|ph].
    { eapply narm_reach; [exact nrules_sound_1RB0RD_1LC1RD_1LA1LC_0LB0RD | exact ok_farm1_1_1RB0RD_1LC1RD_1LA1LC_0LB0RD]. }
    exfalso; lia.
