(** ** What this board establishes

    44 of 44 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 44 of them
    collapse to 2 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 0 stride 1, the fill class at threshold 1
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)

(** *** The inner rules: what the nested arms iterate

    0 rule(s), validated like the ladder at both tails opaque. *)
Definition nlad_1RB1LD_0LB1RC_1LD0RB_0LA1LA : list (LRule * list rstep) :=
  [].
Definition nrules_1RB1LD_0LB1RC_1LD0RB_0LA1LA : list LRule := map fst nlad_1RB1LD_0LB1RC_1LD0RB_0LA1LA.
Local Notation nrules := nrules_1RB1LD_0LB1RC_1LD0RB_0LA1LA.

Lemma nladder_ok_1RB1LD_0LB1RC_1LD0RB_0LA1LA : check_ladder tm [] nlad_1RB1LD_0LB1RC_1LD0RB_0LA1LA = true.
Proof. vm_compute. reflexivity. Qed.

Lemma nrules_sound_1RB1LD_0LB1RC_1LD0RB_0LA1LA : Forall (RuleSound tm false false) nrules.
Proof. apply rule_sound_nil. exact nladder_ok_1RB1LD_0LB1RC_1LD0RB_0LA1LA. Qed.

Definition iarm0_0_1RB1LD_0LB1RC_1LD0RB_0LA1LA : LRule :=
  mkLRule (mkC StC (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []))
          (mkC StC (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 [])) 0 1.
Definition ch_iarm0_0_1RB1LD_0LB1RC_1LD0RB_0LA1LA : list nseg :=
  [NCh [RB (SRotL 1);RB (SWin 1);RB (SCycL 2 0);RB (SWin 2);RB (SCycR 2);RB (SWin 1);RB (SWinR 4);RB (SUnrotL 1)]].
Lemma ok_iarm0_0_1RB1LD_0LB1RC_1LD0RB_0LA1LA :
  check_narm tm false true nrules iarm0_0_1RB1LD_0LB1RC_1LD0RB_0LA1LA ch_iarm0_0_1RB1LD_0LB1RC_1LD0RB_0LA1LA = true.
Proof. vm_compute. reflexivity. Qed.

Definition farm1_0_1RB1LD_0LB1RC_1LD0RB_0LA1LA : LRule :=
  mkLRule (mkC StC (mkS [S1;S1] [S1;S1] 1 0 []) S0 (mkS [] [] 0 0 []))
          (mkC StC (mkS [S1;S0] [S1;S0] 1 0 [S1;S0;S1;S1]) S0 (mkS [] [] 0 0 [])) 0 1.
Definition ch_farm1_0_1RB1LD_0LB1RC_1LD0RB_0LA1LA : list nseg :=
  [NCh [RB (SWin 2);RB (SCycL 2 0);RB (SWinL 10);RB (SCycR 2);RB (SWin 2);RB (SWinR 1);RB (SUnrotL 1)]].
