Lemma bootl_1RB1RD_1LC0RD_1LA1LB_0LC1RD :
  stepn tm 10 InitES = Some (lift (fam_cfg FAM ([0;1;1], 0, 0))).
Proof.
  assert (H : match csteps tm 10 c0 with
              | Some c => ceqb c (fam_cfg FAM ([0;1;1], 0, 0))
              | None => false end = true) by (vm_compute; reflexivity).
  destruct (csteps tm 10 c0) as [c|] eqn:E; [|discriminate].
